1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type Result = { premium: number } | { payout: number; remainingCap: number };
41	
42	const PROCESSING_FEE = 5;
43	
44	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
45	
46	const BASE_PREMIUMS: Record<string, number> = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	  potion: 40,
51	  rune: 25,
52	  moonstone: 25,
53	};
54	
55	/** Premiums round in the MHPCO's favour: always up. */
56	const roundPremium = (premium: number): number => Math.ceil(premium);
57	
58	/**
59	 * Exactly this many items of one type form a "building block", priced at a flat
60	 * rate instead of per item. A larger group is NOT a block -- 4 runes pay 4x25 G.
61	 */
62	const BLOCK_SIZE = 3;
63	const BLOCK_BASE_PREMIUM = 60;
64	
65	/** How many items of each type the policy covers -- the unit the block rule applies to. */
66	const countItemsPerType = (items: Item[]): Map<string, number> =>
67	  items.reduce(
68	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
69	    new Map<string, number>(),
70	  );
71	
72	/**
73	 * The per-item rate for a type. Unknown types price at 0 G for now; the spec
74	 * calls for an error (not yet tested).
75	 */
76	const itemBasePremium = (type: string): number => BASE_PREMIUMS[type] ?? 0;
77	
78	const groupBasePremium = (type: string, count: number): number =>
79	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * itemBasePremium(type);
80	
81	const policyBasePremium = (items: Item[]): number =>
82	  [...countItemsPerType(items)].reduce(
83	    (total, [type, count]) => total + groupBasePremium(type, count),
84	    0,
85	  );
86	
87	/** A customer with AT LEAST this many years of business is long-standing. */
88	const LOYALTY_THRESHOLD_YEARS = 2;
89	const LOYALTY_DISCOUNT_RATE = 0.2;
90	
91	/** Every contract after the customer's first in a scenario is a follow-up. */
92	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
93	
94	const CURSE_SURCHARGE_RATE = 0.5;
95	
96	/** An enchantment AT this level or above is "high" -- level 4 carries no surcharge. */
97	const HIGH_ENCHANTMENT_LEVEL = 5;
98	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
99	
100	/** Item-scoped surcharges stack additively: a cursed, highly enchanted item pays both. */
101	const itemSurchargeRate = (item: Item): number =>
102	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
103	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
104	
105	/** Item-scoped surcharges apply to the affected item's own base premium. */
106	const itemSurchargeTotal = (items: Item[]): number =>
107	  items.reduce(
108	    (total, item) => total + itemBasePremium(item.type) * itemSurchargeRate(item),
109	    0,
110	  );
111	
112	const isLongStanding = (customer: Customer): boolean =>
113	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
114	
115	/**
116	 * Policy-scoped modifiers apply to the policy base premium, never to item
117	 * surcharges. They stack additively, like the item-scoped ones: the
118	 * first-insurance surcharge adds, the loyalty and follow-up discounts
119	 * subtract, each computed against the untouched policy base.
120	 *
121	 * Returns the modifier AMOUNT, not a multiplier on the base. Folding this into
122	 * `policyBase * (1 + rate)` is algebraically identical but NOT identical in
123	 * floating point: 100 * 1.1 is 110.00000000000001, which `roundPremium` ceils
124	 * to 111 G. Keeping base and modifier as separate addends keeps the exact
125	 * values the spec's worked examples expect.
126	 */
127	const policyModifierTotal = (
128	  policyBase: number,
129	  customer: Customer,
130	  isFollowUpContract: boolean,
131	): number =>
132	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE -
133	  (isLongStanding(customer) ? policyBase * LOYALTY_DISCOUNT_RATE : 0) -
134	  (isFollowUpContract ? policyBase * FOLLOW_UP_DISCOUNT_RATE : 0);
135	
136	const quote = (
137	  step: QuoteStep,
138	  customer: Customer,
139	  isFollowUpContract: boolean,
140	): Result => {
141	  const policyBase = policyBasePremium(step.items);
142	  return {
143	    premium: roundPremium(
144	      policyBase +
145	        policyModifierTotal(policyBase, customer, isFollowUpContract) +
146	        itemSurchargeTotal(step.items) +
147	        PROCESSING_FEE,
148	    ),
149	  };
150	};
151	
152	/**
153	 * A quote is a follow-up contract if any contract preceded it in the scenario.
154	 * Counting the quote steps that precede a step -- rather than reading the step
155	 * index -- keeps the rule correct once claims become steps too, since a claim
156	 * is not a contract and must not make the next quote a follow-up.
157	 */
158	const isFollowUpContract = (precedingSteps: Step[]): boolean =>
159	  precedingSteps.some((step) => step.op === "quote");
160	
161	const INSURANCE_VALUES: Record<string, number> = {
162	  sword: 1000,
163	  amulet: 600,
164	  staff: 800,
165	  potion: 400,
166	  rune: 250,
167	  moonstone: 250,
168	};
169	
170	const DEDUCTIBLE_PER_DAMAGE = 100;
171	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
172	
173	const insuranceSum = (items: Item[]): number =>
174	  items.reduce((sum, item) => sum + (INSURANCE_VALUES[item.type] ?? 0), 0);
175	
176	/** A policy, once quoted, tracks how much of its cap is still available. */
177	interface Policy {
178	  items: Item[];
179	  remainingCap: number;
180	}
181	
182	/** Payouts round in the MHPCO's favour: always down. */
183	const roundPayout = (payout: number): number => Math.floor(payout);
184	
185	const claim = (step: ClaimStep, policy: Policy): Result => {
186	  const desired = step.incident.damages.reduce(
187	    (total, damage) => total + Math.max(damage.amount - DEDUCTIBLE_PER_DAMAGE, 0),
188	    0,
189	  );
190	  const payout = roundPayout(Math.min(desired, policy.remainingCap));
191	  policy.remainingCap -= payout;
192	  return { payout, remainingCap: policy.remainingCap };
193	};
194	
195	export const runScenario = (scenario: Scenario): { results: Result[] } => {
196	  const policies = new Map<number, Policy>();
197	  const results: Result[] = [];
198	
199	  scenario.steps.forEach((step, stepIndex) => {
200	    if (step.op === "quote") {
201	      results.push(
202	        quote(step, scenario.customer, isFollowUpContract(scenario.steps.slice(0, stepIndex))),
203	      );
204	      policies.set(stepIndex, {
205	        items: step.items,
206	        remainingCap: insuranceSum(step.items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
207	      });
208	      return;
209	    }
210	    const policy = policies.get(step.policy);
211	    if (!policy) throw new Error(`No policy created by step ${step.policy}`);
212	    results.push(claim(step, policy));
213	  });
214	
215	  return { results };
216	};
217

